// ==============================
// n8n Weekly Dev Summary — Bounty #5
// Fetch GitHub Data (commits, issues, PRs)
// ==============================

const repoOwner = $json.repoOwner;
const repoName  = $json.repoName;
const language  = $json.language || 'en';

// --- Calculate week boundaries ---
// Trigger fires Friday 5pm — week is Mon→Fri
const now = new Date();
const dayOfWeek = now.getDay(); // 0=Sun, 5=Fri
const daysSinceMonday = dayOfWeek === 0 ? 6 : dayOfWeek - 1;
const monday = new Date(now);
monday.setDate(now.getDate() - daysSinceMonday);
monday.setHours(0, 0, 0, 0);

const friday = new Date(now);
friday.setHours(23, 59, 59, 0);

const weekStart = monday.toISOString();
const weekEnd   = friday.toISOString();

// --- GitHub API token ---
// Priority: 1) n8n credential 'GitHub PAT'  2) env var GITHUB_TOKEN
let githubToken;
try {
  githubToken = $credentials?.githubPersonalAccessToken?.accessToken;
} catch (e) {
  // credential not configured — fall through
}
githubToken = githubToken || process.env.GITHUB_TOKEN;

if (!githubToken) {
  throw new Error(
    'GitHub token not found. Set it up:\n' +
    '  1) n8n credential: create a "GitHub Personal Access Token" named "GitHub PAT", OR\n' +
    '  2) Environment variable: add GITHUB_TOKEN to your n8n env (docker-compose.yml / .env)'
  );
}

// --- Helper: fetch with pagination support ---
async function fetchGitHub(url, page = 1, accumulated = []) {
  const pageUrl = `${url}&page=${page}&per_page=100`;
  const response = await fetch(pageUrl, {
    headers: {
      'Authorization': `Bearer ${githubToken}`,
      'Accept': 'application/vnd.github.v3+json',
      'User-Agent': 'n8n-weekly-dev-summary'
    }
  });
  if (!response.ok) {
    const body = await response.text();
    throw new Error(`GitHub API error ${response.status}: ${body}`);
  }
  const data = await response.json();
  const all = accumulated.concat(data);
  // Check Link header for next page
  const linkHeader = response.headers.get('Link');
  if (linkHeader && linkHeader.includes('rel="next"')) {
    return fetchGitHub(url, page + 1, all);
  }
  return all;
}

// --- Fetch commits (since/until) ---
const commits = await fetchGitHub(
  `https://api.github.com/repos/${repoOwner}/${repoName}/commits?since=${weekStart}&until=${weekEnd}`
);

// --- Fetch closed issues ---
const allIssues = await fetchGitHub(
  `https://api.github.com/repos/${repoOwner}/${repoName}/issues?state=closed&since=${weekStart}&filter=all`
);
const actualIssues = allIssues.filter(i => !i.pull_request);

// --- Fetch PRs, then filter by merged_at within the week ---
const allPrs = await fetchGitHub(
  `https://api.github.com/repos/${repoOwner}/${repoName}/pulls?state=all&sort=updated&direction=desc`
);
const mondayMs = monday.getTime();
const fridayMs = friday.getTime();
const mergedPrs = allPrs.filter(pr => {
  if (!pr.merged_at) return false;
  const mergedMs = new Date(pr.merged_at).getTime();
  return mergedMs >= mondayMs && mergedMs <= fridayMs;
});

// --- Return structured output ---
return {
  commits: commits.map(c => ({
    author: c.commit.author.name,
    message: c.commit.message.split('\\n')[0],
    url: c.html_url,
    date: c.commit.author.date,
    sha: c.sha ? c.sha.substring(0, 7) : null
  })),
  issues: actualIssues.map(i => ({
    number: i.number,
    title: i.title,
    state: i.state,
    url: i.html_url,
    closedAt: i.closed_at
  })),
  pullRequests: mergedPrs.map(pr => ({
    number: pr.number,
    title: pr.title,
    author: pr.user.login,
    url: pr.html_url,
    mergedAt: pr.merged_at
  })),
  weekStart: weekStart.substring(0, 10),
  weekEnd: weekEnd.substring(0, 10),
  repoOwner,
  repoName,
  language,
  deliveryEmail: $json.deliveryEmail,
  deliveryWebhook: $json.deliveryWebhook
};

// ==============================
// Build Claude prompt from fetched data
// ==============================

const { commits, issues, pullRequests, weekStart, weekEnd, repoOwner, repoName, language } = $json;

const totalCommits = commits.length;
const totalIssues  = issues.length;
const totalPRs     = pullRequests.length;

// Format data for the prompt
const commitLines = commits.map(c => `  - \`${c.sha || '------'}\` ${c.message} (${c.author})`).join('\\n');
const issueLines  = issues.map(i => `  - [#${i.number}](${i.url}): ${i.title}`).join('\\n');
const prLines     = pullRequests.map(pr => `  - [#${pr.number}](${pr.url}): ${pr.title} by @${pr.author}`).join('\\n');

// System prompt (i18n)
const systemPrompt = language === 'ar'
  ? 'أنت مساعد متخصص في كتابة ملخصات أسبوعية لتطوير المشاريع البرمجية. اكتب الملخص باللغة العربية الفصحى الواضحة. كن موجزاً ومفيداً.'
  : 'You are an expert engineering assistant that writes concise weekly development summaries for software projects. Write in clear, professional English. Be concise and highlight meaningful changes.';

// User prompt (i18n)
const userPrompt = language === 'ar'
  ? `## ملخص التطوير الأسبوعي
\n` +
    `**الأسبوع:** ${weekStart} → ${weekEnd}\n` +
    `**المشروع:** ${repoOwner}/${repoName}\n\n` +
    `### الإحصائيات\n` +
    `- إجمالي Commits: ${totalCommits}\n` +
    `- Issues مغلقة: ${totalIssues}\n` +
    `- Pull Requests مدمجة: ${totalPRs}\n\n` +
    `### سجل Commits\n${commitLines || '  (لا توجد commits هذا الأسبوع)'}\n\n` +
    `### Issues المغلقة\n${issueLines || '  (لا توجد issues مغلقة هذا الأسبوع)'}\n\n` +
    `### Pull Requests المدمجة\n${prLines || '  (لا توجد PRs مدمجة هذا الأسبوع)'}\n\n` +
    `الرجاء كتابة ملخص سردي (2-3 فقرات) يصف أهم التغييرات والإنجازات هذا الأسبوع. اذكر الإحصائيات الرئيسية وأبرز المساهمات.`
  : `## Weekly Development Summary\n\n` +
    `**Week:** ${weekStart} → ${weekEnd}\n` +
    `**Repository:** ${repoOwner}/${repoName}\n\n` +
    `### Stats\n` +
    `- Total Commits: ${totalCommits}\n` +
    `- Closed Issues: ${totalIssues}\n` +
    `- Merged PRs: ${totalPRs}\n\n` +
    `### Commit Log\n${commitLines || '  (no commits this week)'}\n\n` +
    `### Closed Issues\n${issueLines || '  (no issues closed this week)'}\n\n` +
    `### Merged Pull Requests\n${prLines || '  (no PRs merged this week)'}\n\n` +
    `Please write a narrative summary (2-3 paragraphs) describing the key changes and accomplishments this week. Mention the key stats and highlight notable contributions.`;

return {
  systemPrompt,
  userPrompt,
  model: 'claude-sonnet-4-20250514',
  maxTokens: 1500,
  repoOwner,
  repoName,
  weekStart,
  weekEnd,
  deliveryEmail: $json.deliveryEmail,
  deliveryWebhook: $json.deliveryWebhook,
  language,
  stats: {
    totalCommits,
    totalIssues,
    totalPRs
  }
};

// ==============================
// Extract & format Claude's response
// ==============================

const response = $json;

// Handle different response shapes
let summary = '';
if (response.content && Array.isArray(response.content)) {
  summary = response.content
    .filter(block => block.type === 'text')
    .map(block => block.text)
    .join('\\n\\n');
} else if (typeof response.content === 'string') {
  summary = response.content;
} else if (typeof response === 'string') {
  summary = response;
} else {
  summary = JSON.stringify(response, null, 2);
}

return {
  summary,
  repoOwner: $json.repoOwner,
  repoName: $json.repoName,
  weekStart: $json.weekStart,
  weekEnd: $json.weekEnd,
  deliveryEmail: $json.deliveryEmail,
  deliveryWebhook: $json.deliveryWebhook,
  language: $json.language,
  stats: $json.stats
};
